.desktop {
	color: var(--asam-color-text-primary);
	background: var(--asam-color-surface);
	font-family: var(--asam-typography-font-family);
	--desktop-accent: var(--asam-color-primary);
	--asam-color-text-secondary: var(--asam-color-text-regular);
	min-width: 0;
	overflow-wrap: anywhere;
}
.desktop *,
.desktop *::before,
.desktop *::after {
	box-sizing: border-box;
}
.desktop h1,
.desktop h2,
.desktop p {
	margin: 0;
}
.desktop :focus-visible {
	outline: 2px solid var(--desktop-accent);
	outline-offset: 3px;
}
.desktop button:not([class*='el-']) {
	font: inherit;
}
.desktop-stage {
	min-width: 0;
}
.desktop-launcher {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 12px;
	padding-block: 16px;
}
.desktop-launch-symbol {
	display: inline-grid;
	place-items: center;
	width: 20px;
	height: 20px;
	margin-right: 8px;
	background: var(--asam-color-surface-info);
	color: var(--desktop-accent);
	font-size: 12px;
}
.desktop-tools {
	display: flex;
	justify-content: flex-end;
	flex-wrap: wrap;
	align-items: center;
	gap: 8px;
	padding-block: 8px 14px;
	font-size: 12px;
}
.desktop-tools [role='status'] {
	margin-right: auto;
	color: var(--asam-color-text-secondary);
}
.desktop-surface {
	position: relative;
	height: clamp(480px, 65dvh, 720px);
	min-width: 0;
	overflow: hidden;
	isolation: isolate;
	background: var(--asam-color-surface);
	border: 1px solid var(--asam-color-border);
}
.desktop-idle {
	position: absolute;
	inset: 0;
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	text-align: center;
	gap: 16px;
	padding: 24px;
}
.desktop-idle > span {
	font-size: 11px;
	letter-spacing: 0.14em;
	color: var(--asam-color-text-secondary);
}
.desktop-idle h2 {
	font-size: clamp(22px, 3vw, 36px);
	font-weight: 500;
}
.desktop-window {
	position: absolute;
	top: 0;
	left: 0;
	display: flex;
	flex-direction: column;
	border: 1px solid var(--asam-color-border);
	border-radius: var(--asam-radius-default, 8px);
	background: var(--asam-color-surface);
	overflow: hidden;
	animation: desktop-enter 180ms cubic-bezier(0.2, 0.7, 0.3, 1) both;
}
.desktop-window.is-active {
	border-color: var(--desktop-accent);
	box-shadow: var(--asam-shadow-card);
}
.desktop-titlebar {
	display: flex;
	align-items: center;
	gap: var(--asam-space-sm, 8px);
	min-height: 46px;
	padding: 5px 8px;
	border-bottom: 1px solid var(--asam-color-border);
	background: var(--asam-color-surface);
	flex-shrink: 0;
}
.desktop-move {
	min-width: 0;
	flex: 1;
	display: flex;
	align-items: center;
	gap: 8px;
	border: 0;
	background: transparent;
	color: inherit;
	text-align: left;
	cursor: grab;
	touch-action: none;
	padding: 6px 2px;
}
.desktop-move strong {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	font-size: 14px;
}
.desktop-grip {
	color: var(--asam-color-text-secondary);
}
.desktop-window-actions {
	display: flex;
	flex-shrink: 0;
	gap: 4px;
}
.desktop-window-actions button:not([class*='el-']) {
	min-width: 28px;
	padding-inline: 6px;
}
.desktop-window-content {
	min-height: 0;
	flex: 1;
	overflow: auto;
	overscroll-behavior: contain;
	padding: 18px 20px 26px;
}
.desktop-window-content .asam-page-container {
	padding: 0;
}
.desktop-window-content .asam-page-container-header:empty {
	display: none;
}
.desktop-panel-description {
	color: var(--asam-color-text-secondary);
	font-size: 12px;
	margin-bottom: 12px !important;
}
.desktop-resize {
	position: absolute;
	right: 0;
	bottom: 0;
	width: 28px;
	height: 28px;
	cursor: nwse-resize;
	touch-action: none;
	color: var(--desktop-accent);
	border: 0;
	background: var(--asam-color-surface);
}
.desktop button:not([class*='el-']):disabled {
	cursor: not-allowed;
}
.desktop-taskbar {
	display: flex;
	align-items: center;
	gap: 8px;
	padding-block: 14px;
	overflow-x: auto;
	min-height: 60px;
}
.desktop-taskbar > * {
	flex-shrink: 0;
}
.desktop-taskbar-label {
	font-size: 12px;
	color: var(--asam-color-text-secondary);
	margin-right: 12px;
}
.desktop-taskbar [aria-pressed='true'] {
	box-shadow: inset 0 -2px var(--desktop-accent);
}
.desktop-footer {
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
	gap: 8px;
	font-size: 11px;
	letter-spacing: 0.04em;
	color: var(--asam-color-text-secondary);
	padding-block: 12px 20px;
}
.desktop-stage[data-narrow='true'] .desktop-surface {
	height: min(65dvh, 640px);
	min-height: 360px;
}
.desktop-stage[data-size='small'] .desktop-titlebar {
	min-height: 40px;
}
.desktop-stage[data-size='big'] .desktop-titlebar {
	min-height: 50px;
}
.desktop-stage[data-size='large'] .desktop-titlebar {
	min-height: 54px;
}
.desktop-minimal {
	padding: 24px clamp(16px, 4vw, 56px) 0;
}
.desktop-edition {
	display: flex;
	flex-wrap: wrap;
	justify-content: space-between;
	border-bottom: 2px solid var(--asam-color-text-primary);
	padding-bottom: 12px;
	font-size: 11px;
	letter-spacing: 0.12em;
}
.desktop-intro {
	padding-block: 28px 20px;
	display: flex;
	align-items: flex-end;
	justify-content: space-between;
	gap: 24px;
}
.desktop-intro h1 {
	font-family: Georgia, 'Songti SC', serif;
	font-weight: 500;
	font-size: clamp(28px, 3vw, 44px);
	letter-spacing: -0.04em;
}
.desktop-intro p {
	max-width: 30em;
	font-size: 13px;
	line-height: 1.8;
	color: var(--asam-color-text-secondary);
}
.desktop-minimal .desktop-surface {
	background-image: radial-gradient(var(--asam-color-border) 0.6px, transparent 0.6px);
	background-size: 16px 16px;
}
.desktop-minimal .desktop-window {
	border-radius: 4px;
}
.desktop-brand {
	display: grid;
	grid-template-columns: 244px minmax(0, 1fr);
	min-height: 100%;
}
.desktop-brand-rail {
	padding: 36px 28px;
	display: flex;
	flex-direction: column;
	background: var(--asam-semantic-brand-surface);
	color: var(--asam-semantic-brand-foreground);
	overflow: hidden;
}
.desktop-wordmark {
	color: inherit;
	font-size: 30px;
	font-weight: 700;
	letter-spacing: -0.06em;
	text-decoration: none;
}
.desktop-wordmark span {
	display: block;
	font-size: 10px;
	letter-spacing: 0.22em;
	margin-top: 8px;
}
.desktop-brand-story {
	margin-block: 64px 32px;
}
.desktop-brand-story h1 {
	font-size: 32px;
	line-height: 1.5;
	letter-spacing: -0.04em;
	margin-block: 16px;
}
.desktop-brand-story p {
	font-size: 12px;
	line-height: 1.9;
}
.desktop-brand-rail nav a {
	color: inherit;
}
.desktop.desktop-brand .desktop-brand-rail nav a {
	color: var(--asam-semantic-brand-foreground);
}
.desktop-brand-mark {
	margin-top: auto;
	padding-top: 48px;
	font-size: 120px;
	line-height: 1;
	letter-spacing: -0.12em;
	opacity: 0.2;
}
.desktop-brand-main {
	padding: 28px clamp(16px, 3vw, 40px) 0;
	min-width: 0;
}
.desktop-brand-top {
	display: flex;
	justify-content: space-between;
	flex-wrap: wrap;
	gap: 8px;
	padding-bottom: 22px;
	border-bottom: 1px solid var(--asam-color-border);
}
.desktop-brand-top strong {
	font-size: 24px;
	font-weight: 500;
}
.desktop-brand-top span {
	color: var(--asam-color-text-secondary);
	font-size: 12px;
}
.desktop-brand .desktop-surface {
	border-radius: 12px;
}
.desktop-brand .desktop-window {
	border-radius: 10px;
}
.desktop-tech {
	padding: 24px clamp(12px, 3vw, 40px) 0;
}
.desktop-tech-top {
	display: flex;
	flex-wrap: wrap;
	align-items: flex-end;
	justify-content: space-between;
	gap: 20px;
	border-bottom: 2px solid var(--desktop-accent);
	padding-bottom: 24px;
}
.desktop-tech-kicker {
	font:
		11px ui-monospace,
		monospace;
	letter-spacing: 0.16em;
	color: var(--desktop-accent);
}
.desktop-tech-top h1 {
	margin-top: 16px;
	font-size: clamp(28px, 4vw, 48px);
	font-weight: 500;
	letter-spacing: -0.04em;
}
.desktop-tech-top p {
	font-size: 12px;
	color: var(--asam-color-text-secondary);
}
.desktop-tech-grid {
	display: grid;
	grid-template-columns: 52px minmax(0, 1fr);
	gap: 20px;
}
.desktop-tech-index {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 24px;
	padding-top: 24px;
	font:
		10px ui-monospace,
		monospace;
	color: var(--asam-color-text-secondary);
}
.desktop-tech-index > span:first-child {
	font-size: 30px;
	color: var(--desktop-accent);
}
.desktop-tech-index i {
	width: 1px;
	flex: 1;
	background: var(--asam-color-border);
}
.desktop-tech-index small {
	font-size: 9px;
	padding-bottom: 16px;
}
.desktop-tech .desktop-window {
	border-radius: 0;
	border-width: 1px;
}
.desktop-tech .desktop-titlebar {
	border-left: 3px solid var(--desktop-accent);
}
.desktop-tech .desktop-surface {
	background-image:
		linear-gradient(var(--asam-color-border) 1px, transparent 1px),
		linear-gradient(90deg, var(--asam-color-border) 1px, transparent 1px);
	background-size: 48px 48px;
}
.desktop-tech .desktop-taskbar {
	border-top: 1px solid var(--asam-color-border);
}
@keyframes desktop-enter {
	from {
		opacity: 0;
	}
	to {
		opacity: 1;
	}
}
@media (max-width: 760px) {
	.desktop-intro {
		align-items: flex-start;
		flex-direction: column;
		gap: 12px;
	}
	.desktop-brand {
		grid-template-columns: minmax(0, 1fr);
	}
	.desktop-brand-rail {
		padding: 18px 20px;
		display: grid;
		grid-template-columns: auto minmax(0, 1fr);
		align-items: center;
		gap: 12px;
	}
	.desktop-brand-story {
		margin: 0;
		text-align: right;
	}
	.desktop-brand-story h1 {
		font-size: 18px;
		margin: 0;
	}
	.desktop-brand-story p,
	.desktop-brand-mark {
		display: none;
	}
	.desktop-brand-rail nav {
		grid-column: 1 / -1;
	}
	.desktop-tech-grid {
		grid-template-columns: minmax(0, 1fr);
	}
	.desktop-tech-index {
		display: none;
	}
	.desktop-launcher {
		gap: 8px;
	}
	.desktop-window-content {
		padding-inline: 14px;
	}
}
@media (prefers-reduced-motion: reduce) {
	.desktop-window {
		animation: none;
	}
	.desktop *,
	.desktop *::before,
	.desktop *::after {
		transition-duration: 0s !important;
		scroll-behavior: auto !important;
	}
}

import { computed, readonly, ref, shallowRef } from 'vue';
import { createBusinessCache } from '@asam-ui/pro/application/preferences';
import { encodeScope } from '@asam-ui/pro/application/preferences';
import type { Scope, StorageAdapter } from '@asam-ui/pro/application/preferences';
import type {
	DesktopOptions,
	DesktopPanel,
	DesktopWindow,
	LayoutSnapshot,
	LayoutStatus,
	WindowRect
} from './Types.js';

const copy = <T>(v: T): T => JSON.parse(JSON.stringify(v));
const record = (v: unknown): v is Record<string, unknown> =>
	typeof v === 'object' && v !== null && !Array.isArray(v);
const exact = (v: Record<string, unknown>, keys: string[]) =>
	Object.keys(v).length === keys.length && keys.every((k) => Object.hasOwn(v, k));
const rectValid = (v: unknown): v is WindowRect =>
	record(v) &&
	exact(v, ['x', 'y', 'width', 'height']) &&
	Object.values(v).every(
		(n) => typeof n === 'number' && Number.isFinite(n) && Math.abs(n) <= 100000
	) &&
	Number(v.width) > 0 &&
	Number(v.height) > 0;
export function validateLayout(v: unknown): v is LayoutSnapshot {
	if (
		!record(v) ||
		!exact(v, ['version', 'windows', 'active']) ||
		v.version !== 1 ||
		!Array.isArray(v.windows) ||
		v.windows.length > 32
	)
		return false;
	const ids = new Set<string>();
	for (const w of v.windows) {
		if (
			!record(w) ||
			!exact(w, ['id', 'rect', 'minimized', 'maximized']) ||
			typeof w.id !== 'string' ||
			!w.id ||
			w.id.length > 128 ||
			ids.has(w.id) ||
			!rectValid(w.rect) ||
			typeof w.minimized !== 'boolean' ||
			typeof w.maximized !== 'boolean'
		)
			return false;
		ids.add(w.id);
	}
	return (
		v.active === null ||
		(typeof v.active === 'string' &&
			ids.has(v.active) &&
			!v.windows.find((w) => w.id === v.active)?.minimized)
	);
}
export function clampRect(rect: WindowRect, width: number, height: number): WindowRect {
	const w = Math.max(1, width),
		h = Math.max(1, height);
	const rw = Math.min(w, Math.max(Math.min(280, w), rect.width));
	const rh = Math.min(h, Math.max(Math.min(180, h), rect.height));
	return {
		x: Math.max(0, Math.min(w - rw, rect.x)),
		y: Math.max(0, Math.min(h - rh, rect.y)),
		width: rw,
		height: rh
	};
}
function panelsCopy(input: readonly DesktopPanel[]): DesktopPanel[] {
	if (!Array.isArray(input) || input.length > 32) throw Error('At most 32 local panels');
	const ids = new Set<string>();
	return input.map((p) => {
		if (
			!p.id ||
			p.id.length > 128 ||
			ids.has(p.id) ||
			!p.title ||
			typeof p.allowed !== 'boolean'
		)
			throw Error('Invalid panel allowlist');
		ids.add(p.id);
		if (
			p.initial &&
			Object.values(p.initial).some((n) => typeof n !== 'number' || !Number.isFinite(n))
		)
			throw Error('Invalid initial rect');
		return copy(p);
	});
}
/** One instance owns layout only. The host owns business requests and child content. */
export function createDesktop(options: DesktopOptions) {
	if (!options.app) throw Error('Missing desktop application namespace');
	const panels = shallowRef(panelsCopy(options.panels));
	const windows = shallowRef<DesktopWindow[]>([]);
	const active = ref<string | null>(null);
	const viewport = ref({ width: 1100, height: 620 });
	const breakpoint = options.breakpoint ?? 720;
	if (!Number.isFinite(breakpoint) || breakpoint < 280) throw Error('Invalid breakpoint');
	const narrow = computed(() => viewport.value.width < breakpoint);
	const disabled = ref(options.disabled ?? false),
		readOnly = ref(options.readonly ?? false);
	const status = ref<LayoutStatus>('missing');
	const revision = ref(0),
		focusRevision = ref(0),
		contextRevision = ref(0);
	let owner = JSON.parse(encodeScope(options.owner)) as Scope;
	let scope = JSON.parse(encodeScope(options.scope)) as Scope;
	let epoch = 0,
		disposed = false,
		baseline: string | null | undefined;
	let baselineRevision = 0;
	function rememberBaseline(value: string | null | undefined) {
		baseline = value;
		baselineRevision++;
	}
	let writingEpoch: number | undefined;
	let writingContext: object | undefined;
	let writingBaseline: string | null | undefined,
		writeConflict = false;
	const guardedStorage: StorageAdapter | undefined = options.storage && {
		getItem: (key: string) => options.storage!.getItem(key),
		setItem: (key: string, value: string) => {
			const context = writingContext;
			if (disposed || writingEpoch !== epoch || context !== cache)
				throw Error('Stale layout write');
			const current = options.storage!.getItem(key);
			if (disposed || writingEpoch !== epoch || context !== cache)
				throw Error('Stale layout write');
			if (current !== writingBaseline) {
				writeConflict = true;
				throw Error('Layout conflict');
			}
			options.storage!.setItem(key, value);
			if (!disposed && context === cache) rememberBaseline(value);
		},
		removeItem: (key: string) => {
			const context = cache;
			options.storage!.removeItem(key);
			if (!disposed && context === cache) rememberBaseline(null);
		}
	};
	const cacheFor = () =>
		createBusinessCache<LayoutSnapshot>({
			app: `${options.app}/desktop-layout`,
			owner,
			scope,
			storage: guardedStorage,
			version: 1,
			ttl: options.ttl ?? 30 * 24 * 60 * 60 * 1000,
			now: options.now,
			validate: validateLayout
		});
	let cache = cacheFor();
	const visiblePanels = computed(() => panels.value.filter((p) => p.allowed));
	const panel = (id: string) => panels.value.find((p) => p.id === id && p.allowed);
	const allowed = (id: string) =>
		!disposed && !disabled.value && !readOnly.value && !!panel(id) && !panel(id)?.disabled;
	const raw = () => {
		try {
			return options.storage?.getItem(cache.key());
		} catch {
			return undefined;
		}
	};
	const touch = () => {
		epoch++;
		revision.value++;
	};
	function focus(id: string | null) {
		active.value = id;
		focusRevision.value++;
	}
	function fallback() {
		focus([...windows.value].reverse().find((w) => !w.minimized)?.id ?? null);
	}
	function initialRect(p: DesktopPanel, i: number): WindowRect {
		return { x: 28 + i * 64, y: 26 + i * 52, width: 460, height: 330, ...p.initial };
	}
	function defaults() {
		windows.value = panels.value
			.filter((p) => p.allowed && p.initialOpen)
			.map((p, i) => ({
				id: p.id,
				rect: initialRect(p, i),
				minimized: false,
				maximized: false
			}));
		fallback();
	}
	function snapshot(): LayoutSnapshot {
		return copy({ version: 1, windows: windows.value, active: active.value });
	}
	function restoreSnapshot(value: LayoutSnapshot) {
		windows.value = copy(value.windows.filter((w) => !!panel(w.id)));
		focus(
			value.active && windows.value.some((w) => w.id === value.active && !w.minimized)
				? value.active
				: ([...windows.value].reverse().find((w) => !w.minimized)?.id ?? null)
		);
	}
	function open(id: string): boolean {
		if (!allowed(id)) return false;
		const existing = windows.value.find((w) => w.id === id);
		if (!existing)
			windows.value = [
				...windows.value,
				{
					id,
					rect: initialRect(
						panel(id)!,
						panels.value.findIndex((p) => p.id === id)
					),
					minimized: false,
					maximized: false
				}
			];
		return activate(id);
	}
	function activate(id: string): boolean {
		if (!allowed(id) || !windows.value.some((w) => w.id === id)) return false;
		const w = windows.value.find((w) => w.id === id)!;
		windows.value = [...windows.value.filter((w) => w.id !== id), { ...w, minimized: false }];
		touch();
		focus(id);
		return true;
	}
	function change(id: string, operation: 'close' | 'minimize' | 'maximize'): boolean {
		if (!allowed(id) || !windows.value.some((w) => w.id === id)) return false;
		if (operation === 'close') windows.value = windows.value.filter((w) => w.id !== id);
		else if (operation === 'minimize')
			windows.value = windows.value.map((w) => (w.id !== id ? w : { ...w, minimized: true }));
		else {
			const target = windows.value.find((w) => w.id === id)!;
			windows.value = [
				...windows.value.filter((w) => w.id !== id),
				{ ...target, minimized: false, maximized: !target.maximized }
			];
		}
		touch();
		if (operation === 'maximize') focus(id);
		else if (active.value === id) fallback();
		return true;
	}
	function setRect(id: string, value: WindowRect): boolean {
		if (!allowed(id) || narrow.value || !rectValid(value)) return false;
		const w = windows.value.find((w) => w.id === id);
		if (!w || w.maximized || w.minimized) return false;
		windows.value = windows.value.map((w) =>
			w.id === id
				? { ...w, rect: clampRect(value, viewport.value.width, viewport.value.height) }
				: w
		);
		touch();
		return true;
	}
	function displayRect(w: Readonly<DesktopWindow>): WindowRect {
		return narrow.value || w.maximized
			? { x: 0, y: 0, ...viewport.value }
			: clampRect(w.rect, viewport.value.width, viewport.value.height);
	}
	function setViewport(width: number, height: number) {
		if (
			disposed ||
			!Number.isFinite(width) ||
			!Number.isFinite(height) ||
			width <= 0 ||
			height <= 0
		)
			return;
		viewport.value = { width, height }; // Projection only; never rewrite saved desktop positions.
	}
	async function restore(beforeRead?: () => Promise<void>): Promise<LayoutStatus> {
		if (disposed) return 'disposed';
		const token = ++epoch;
		try {
			await beforeRead?.();
		} catch {
			if (disposed || token !== epoch) return 'stale';
			status.value = 'unavailable';
			return 'unavailable';
		}
		if (disposed || token !== epoch) return 'stale';
		const before = raw();
		if (disposed || token !== epoch) return 'stale';
		const result = cache.read('layout');
		// Storage adapters are host code: a getItem callback may reenter this controller.
		if (disposed || token !== epoch) return 'stale';
		const observed = raw();
		if (disposed || token !== epoch) return 'stale';
